#include <stdio.h>
#include <limits.h>
#include <string.h>

#define MAXN 20
#define INF -1000000000

int main() {
    int N, M, K;
    scanf("%d %d %d", &N, &M, &K);

    int compat[MAXN][MAXN];
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            compat[i][j] = 0;

    for (int i = 0; i < M; i++) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        if (c == 0) {
            compat[a][b] = INF;
            compat[b][a] = INF;
        } else {
            compat[a][b] = c;
            compat[b][a] = c;
        }
    }

    int total_masks = 1 << N;
    int dp[total_masks];
    for (int i = 0; i < total_masks; i++)
        dp[i] = INF;
    dp[0] = 0;

    for (int mask = 0; mask < total_masks; mask++) {
        if (dp[mask] == INF) continue;
        for (int v = 0; v < N; v++) {
            if (mask & (1 << v)) continue;
            int ok = 1;
            for (int u = 0; u < N; u++) {
                if (mask & (1 << u)) {
                    if (compat[u][v] == INF) {
                        ok = 0;
                        break;
                    }
                }
            }
            if (ok) {
                int new_mask = mask | (1 << v);
                int add = 0;
                for (int u = 0; u < N; u++) {
                    if (mask & (1 << u))
                        add += compat[u][v];
                }
                int val = dp[mask] + add;
                if (val > dp[new_mask])
                    dp[new_mask] = val;
            }
        }
    }

    int answer = INF;
    for (int mask = 0; mask < total_masks; mask++) {
        if (__builtin_popcount(mask) == K) {
            if (dp[mask] > answer)
                answer = dp[mask];
        }
    }

    if (answer == INF)
        printf("Impossible\n");
    else
        printf("%d\n", answer);

    return 0;
}

