int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    const int INF = 1e9;
    vector<vector<int>> friendVal(N, vector<int>(N, 0));
    vector<vector<bool>> blocked(N, vector<bool>(N, false));

    for (int i = 0; i < M; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        if (c == 0) {
            blocked[a][b] = blocked[b][a] = true;
        } else {
            friendVal[a][b] = friendVal[b][a] = c;
        }
    }

    int totalMasks = 1 << N;
    vector<int> dp(totalMasks, -INF);
    dp[0] = 0;

    // Precompute for each mask whether it contains a blocked pair
    vector<bool> valid(totalMasks, true);
    for (int mask = 0; mask < totalMasks; mask++) {
        for (int i = 0; i < N; i++) if (mask & (1 << i)) {
            for (int j = i+1; j < N; j++) if (mask & (1 << j)) {
                if (blocked[i][j]) {
                    valid[mask] = false;
                    goto nextMask;
                }
            }
        }
        nextMask:;
    }

    for (int mask = 0; mask < totalMasks; mask++) {
        if (!valid[mask] || dp[mask] == -INF) continue;
        for (int i = 0; i < N; i++) {
            if (mask & (1 << i)) continue;
            int newMask = mask | (1 << i);
            if (!valid[newMask]) continue;
            int addVal = 0;
            for (int j = 0; j < N; j++) {
                if (mask & (1 << j)) {
                    addVal += friendVal[i][j];
                }
            }
            dp[newMask] = max(dp[newMask], dp[mask] + addVal);
        }
    }

    int ans = -INF;
    for (int mask = 0; mask < totalMasks; mask++) {
        if (__builtin_popcount(mask) == K && valid[mask]) {
            ans = max(ans, dp[mask]);
        }
    }

    if (ans == -INF) {
        cout << "Impossible\n";
    } else {
        cout << ans << "\n";
    }

    return 0;
}

