int main() {
    int N, M, K;
    cin >> N >> M >> K;

    // friendship[i][j] = c value (0 means forbidden if explicitly 0)
    // forbidden[i][j] = true if c=0
    vector<vector<int>> friendship(N, vector<int>(N, 0));
    vector<vector<bool>> forbidden(N, vector<bool>(N, false));

    for (int i = 0; i < M; i++) {
        int a, b, c;
        cin >> a >> b >> c;
        a--; b--;
        if (c == 0) {
            forbidden[a][b] = forbidden[b][a] = true;
        } else {
            friendship[a][b] = friendship[b][a] = c;
        }
    }

    // dp[mask] = max sum for that subset, or -INF if invalid
    const long long NEG_INF = LLONG_MIN / 2;
    vector<long long> dp(1 << N, NEG_INF);
    dp[0] = 0;

    for (int mask = 0; mask < (1 << N); mask++) {
        if (dp[mask] == NEG_INF) continue;
        int bits = __builtin_popcount(mask);
        if (bits >= K) continue;

        // Find lowest unset bit >= highest set bit to avoid recomputation? No, just try all unset bits > last set
        // To avoid duplicates, only add monsters with index > highest in mask
        int highest = -1;
        for (int i = N-1; i >= 0; i--) if (mask & (1<<i)) { highest = i; break; }

        for (int i = highest + 1; i < N; i++) {
            // Check if i conflicts with any in mask
            bool ok = true;
            long long add = 0;
            for (int j = 0; j < N; j++) {
                if (mask & (1<<j)) {
                    if (forbidden[i][j]) { ok = false; break; }
                    add += friendship[i][j];
                }
            }
            if (ok) {
                int nmask = mask | (1<<i);
                dp[nmask] = max(dp[nmask], dp[mask] + add);
            }
        }
    }

    long long ans = NEG_INF;
    for (int mask = 0; mask < (1<<N); mask++) {
        if (__builtin_popcount(mask) == K) ans = max(ans, dp[mask]);
    }

    if (ans == NEG_INF) cout << "Impossible" << endl;
    else cout << ans << endl;
}

