int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, K;
    cin >> N >> M >> K;

    vector<vector<ll>> w(N, vector<ll>(N, 0));
    vector<vector<int>> bad(N, vector<int>(N, 0));

    for (int i = 0; i < M; ++i) {
        int a, b;
        ll c;
        cin >> a >> b >> c;
        --a; --b;
        if (c == 0) {
            bad[a][b] = bad[b][a] = 1;
        } else {
            w[a][b] = w[b][a] = c;
        }
    }

    int total = 1 << N;

    // ok[mask] = whether mask is an independent set with respect to bad edges
    vector<char> ok(total, 1);
    vector<ll> score(total, 0);

    for (int mask = 1; mask < total; ++mask) {
        int v = __builtin_ctz(mask);
        int pmask = mask ^ (1 << v);

        ok[mask] = ok[pmask];
        if (!ok[mask]) continue;

        ll add = 0;
        for (int u = 0; u < N; ++u) {
            if (pmask & (1 << u)) {
                if (bad[v][u]) {
                    ok[mask] = 0;
                    break;
                }
                add += w[v][u];
            }
        }
        if (ok[mask]) score[mask] = score[pmask] + add;
    }

    ll ans = LLONG_MIN;
    for (int mask = 0; mask < total; ++mask) {
        if (__builtin_popcount((unsigned)mask) == K && ok[mask]) {
            ans = max(ans, score[mask]);
        }
    }

    if (ans == LLONG_MIN) {
        cout << "Impossible\n";
    } else {
        cout << ans << '\n';
    }

    return 0;
}

import java.util.*;

public class SocialMonsters {
    static int N, M, K;
    static int[][] friendship;
    static boolean[][] bad;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextInt();
        M = sc.nextInt();
        K = sc.nextInt();

        friendship = new int[N][N];
        bad = new boolean[N][N];

        for (int i = 0; i < M; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            int c = sc.nextInt();
            if (c == 0) {
                bad[a][b] = bad[b][a] = true;
            } else {
                friendship[a][b] = friendship[b][a] = c;
            }
        }

        // Precompute bad neighbors for quick check
        boolean[] possible = new boolean[1 << N];
        possible[0] = true;
        for (int mask = 1; mask < (1 << N); mask++) {
            int bit = Integer.numberOfTrailingZeros(mask);
            int prev = mask ^ (1 << bit);
            if (!possible[prev]) continue;
            boolean ok = true;
            for (int j = 0; j < N; j++) {
                if ((prev & (1 << j)) != 0 && bad[bit][j]) {
                    ok = false;
                    break;
                }
            }
            possible[mask] = ok;
        }

        int half = N / 2;
        int leftSize = half;
        int rightSize = N - half;

        // Left half: all independent sets, store best weight for each (mask, count)
        Map<Integer, Integer>[] leftBest = new HashMap[leftSize + 1];
        for (int i = 0; i <= leftSize; i++) leftBest[i] = new HashMap<>();

        for (int mask = 0; mask < (1 << leftSize); mask++) {
            if (!possible[mask]) continue;
            int cnt = Integer.bitCount(mask);
            int weight = 0;
            for (int i = 0; i < leftSize; i++) if ((mask & (1 << i)) != 0) {
                for (int j = i+1; j < leftSize; j++) if ((mask & (1 << j)) != 0) {
                    weight += friendship[i][j];
                }
            }
            // store only max weight for given bitmask of right-side neighbors pattern? Actually store by mask itself
            int key = mask; // for left side we just use mask as key later? We'll combine differently.
            leftBest[cnt].merge(mask, weight, Math::max);
        }

        // Right half: similar but we need to consider cross edges
        Map<Integer, Integer>[] rightBest = new HashMap[rightSize + 1];
        for (int i = 0; i <= rightSize; i++) rightBest[i] = new HashMap<>();

        for (int mask = 0; mask < (1 << rightSize); mask++) {
            int shiftedMask = mask << leftSize;
            if (!possible[shiftedMask]) continue;
            int cnt = Integer.bitCount(mask);
            int weight = 0;
            for (int i = 0; i < rightSize; i++) if ((mask & (1 << i)) != 0) {
                int gi = leftSize + i;
                for (int j = i+1; j < rightSize; j++) if ((mask & (1 << j)) != 0) {
                    int gj = leftSize + j;
                    weight += friendship[gi][gj];
                }
            }
            rightBest[cnt].merge(mask, weight, Math::max);
        }

        int answer = -1;
        // combine left and right
        for (int lcnt = 0; lcnt <= leftSize; lcnt++) {
            int rcnt = K - lcnt;
            if (rcnt < 0 || rcnt > rightSize) continue;
            for (var leftEntry : leftBest[lcnt].entrySet()) {
                int lmask = leftEntry.getKey();
                int lw = leftEntry.getValue();
                // find all right masks that are compatible with lmask
                // compatibility: no bad edge between any left chosen and right chosen
                int forbiddenMask = 0;
                for (int i = 0; i < leftSize; i++) if ((lmask & (1 << i)) != 0) {
                    for (int j = 0; j < rightSize; j++) {
                        if (bad[i][leftSize + j]) {
                            forbiddenMask |= (1 << j);
                        }
                    }
                }
                int allowedMask = ((1 << rightSize) - 1) ^ forbiddenMask;
                // iterate over submasks of allowedMask with exactly rcnt bits
                for (int rmask = allowedMask; ; rmask = (rmask - 1) & allowedMask) {
                    if (Integer.bitCount(rmask) == rcnt && rightBest[rcnt].containsKey(rmask)) {
                        int totalWeight = lw + rightBest[rcnt].get(rmask);
                        // add cross edges between left and right
                        for (int i = 0; i < leftSize; i++) if ((lmask & (1 << i)) != 0) {
                            for (int j = 0; j < rightSize; j++) if ((rmask & (1 << j)) != 0) {
                                totalWeight += friendship[i][leftSize + j];
                            }
                        }
                        answer = Math.max(answer, totalWeight);
                    }
                    if (rmask == 0) break;
                }
            }
        }

        if (answer == -1) {
            System.out.println("Impossible");
        } else {
            System.out.println(answer);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Meet-in-the-middle maximum weight independent set of exact size K
    // Weight of a chosen set S:
    //   sum of c(i,j) for all chosen pairs with c != 0
    // and pairs with c = 0 are forbidden.
    //
    // Let base[i][j] be friendship value for normal pairs, 0 if unspecified.
    // For a chosen set S:
    //   total = sum over i<j in S of base[i][j]
    // We split vertices into L and R.
    // For subset A in L and subset B in R:
    //   total(A union B) = wL[A] + wR[B] + cross(A,B)
    // where cross(A,B) = sum_{i in A, j in B} base[i][j]
    // and also no forbidden edge may exist inside A, inside B, or across A,B.
    //
    // For each valid right subset B, define vector:
    //   valA(B) = wR[B] + sum_{i in A} crossSumToSubset[i][B]
    // for each left subset A that is cross-compatible with B.
    // We enumerate left subsets by Gray code. For each left subset A, we need the best
    // valid right subset of size K-|A| among those compatible with A, maximizing valA(B).
    //
    // Compatibility with A means B avoids union of forbidden-neighbor masks in R from vertices in A.
    // So allowed B must be subset of availMask(A).
    //
    // For each size t, on the lattice of masks over R, we precompute:
    //   dp_t[mask] = maximum val over valid right subsets B of size t with B subset of mask
    // under current A-dependent values.
    // Since values change by adding a per-vertex contribution when A changes, we rebuild by SOS DP
    // for each A would be too slow.
    //
    // Instead, because N in this problem is small enough for MITM (typical <= 40), and M arbitrary,
    // we use a branch-and-bound over the smaller side after preprocessing valid subsets.
    //
    // Practical exact solution:
    // - Split N into n1,n2 <= 20.
    // - Enumerate all valid subsets on each side with size and internal weight.
    // - For right valid subsets, group by size.
    // - For each left valid subset A, scan right valid subsets of needed size and test cross-forbidden,
    //   computing total with precomputed cross contribution.
    //
    // This is worst-case heavy, but with n2 <= 20 and only valid subsets surviving forbidden edges,
    // it is accepted for intended constraints.

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class SubsetInfo {
        int mask;
        int size;
        long weight;
        int forbidOtherMask; // for left subset: forbidden vertices in right due to cross zero-edges
        SubsetInfo(int mask, int size, long weight, int forbidOtherMask) {
            this.mask = mask;
            this.size = size;
            this.weight = weight;
            this.forbidOtherMask = forbidOtherMask;
        }
    }

    static int N, M, K;
    static long[][] w;          // friendship values, 0 if unspecified or forbidden
    static boolean[][] bad;     // true if forbidden pair
    static int n1, n2;
    static int[] leftMap, rightMap;

    static long[] crossSumRightToLeftMask; // temporary not used globally

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        M = fs.nextInt();
        K = fs.nextInt();

        w = new long[N][N];
        bad = new boolean[N][N];

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            int c = fs.nextInt();
            // Input indices are 0-based as stated.
            if (c == 0) {
                bad[a][b] = bad[b][a] = true;
            } else {
                w[a][b] = w[b][a] = c;
            }
        }

        if (K > N) {
            System.out.println("Impossible");
            return;
        }

        n1 = N / 2;
        n2 = N - n1;
        leftMap = new int[n1];
        rightMap = new int[n2];
        for (int i = 0; i < n1; i++) leftMap[i] = i;
        for (int i = 0; i < n2; i++) rightMap[i] = n1 + i;

        // Quick maximum independent set size feasibility DP by bitmask on smaller whole graph is not possible.
        // We'll detect impossibility by enumeration result.

        List<SubsetInfo> leftSubs = enumerateSide(true);
        List<SubsetInfo>[] rightBySize = new ArrayList[n2 + 1];
        for (int i = 0; i <= n2; i++) rightBySize[i] = new ArrayList<>();
        List<SubsetInfo> rightSubs = enumerateSide(false);
        for (SubsetInfo s : rightSubs) rightBySize[s.size].add(s);

        // Precompute cross weights for each left mask against each right subset mask by summing per left vertex.
        // For each left subset, we will scan candidate right subsets of needed size.

        long ans = Long.MIN_VALUE;
        boolean found = false;

        // Precompute for each left vertex its cross-forbidden mask in right and cross-weight to each right vertex.
        int[] leftToRightBadMask = new int[n1];
        long[][] leftToRightW = new long[n1][n2];
        for (int i = 0; i < n1; i++) {
            int gi = leftMap[i];
            int mask = 0;
            for (int j = 0; j < n2; j++) {
                int gj = rightMap[j];
                if (bad[gi][gj]) mask |= 1 << j;
                leftToRightW[i][j] = w[gi][gj];
            }
            leftToRightBadMask[i] = mask;
        }

        // For speed: for each left subset mask, precompute forbidden right mask and cross contribution to every right subset by DP.
        int maxRightMask = 1 << n2;
        long[] crossWeightForRightMask = new long[maxRightMask];

        // Group left subsets by mask iteration order for reuse
        for (SubsetInfo L : leftSubs) {
            int need = K - L.size;
            if (need < 0 || need > n2) continue;

            Arrays.fill(crossWeightForRightMask, 0L);
            // Build per-right-subset cross weight from this left subset
            // First compute per-right-vertex sum to L
            long[] perR = new long[n2];
            int tmp = L.mask;
            while (tmp != 0) {
                int bit = tmp & -tmp;
                int i = Integer.numberOfTrailingZeros(bit);
                for (int j = 0; j < n2; j++) perR[j] += leftToRightW[i][j];
                tmp ^= bit;
            }
            for (int mask = 1; mask < maxRightMask; mask++) {
                int bit = mask & -mask;
                int j = Integer.numberOfTrailingZeros(bit);
                crossWeightForRightMask[mask] = crossWeightForRightMask[mask ^ bit] + perR[j];
            }

            int forbiddenMask = L.forbidOtherMask;
            for (SubsetInfo R : rightBySize[need]) {
                if ((R.mask & forbiddenMask) != 0) continue;
                long total = L.weight + R.weight + crossWeightForRightMask[R.mask];
                if (!found || total > ans) ans = total;
                found = true;
            }
        }

        if (!found) System.out.println("Impossible");
        else System.out.println(ans);
    }

    static List<SubsetInfo> enumerateSide(boolean left) {
        int n = left ? n1 : n2;
        int[] map = left ? leftMap : rightMap;
        int otherN = left ? n2 : n1;

        int[] badMaskInside = new int[n];
        int[] badMaskOther = new int[n];
        long[][] insideW = new long[n][n];

        for (int i = 0; i < n; i++) {
            int gi = map[i];
            int maskIn = 0;
            int maskOther = 0;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                int gj = map[j];
                if (bad[gi][gj]) maskIn |= 1 << j;
                insideW[i][j] = w[gi][gj];
            }
            for (int j = 0; j < otherN; j++) {
                int gj = left ? rightMap[j] : leftMap[j];
                if (bad[gi][gj]) maskOther |= 1 << j;
            }
            badMaskInside[i] = maskIn;
            badMaskOther[i] = maskOther;
        }

        int total = 1 << n;
        boolean[] valid = new boolean[total];
        int[] size = new int[total];
        long[] weight = new long[total];
        int[] forbidOther = new int[total];
        valid[0] = true;

        List<SubsetInfo> res = new ArrayList<>();
        res.add(new SubsetInfo(0, 0, 0L, 0));

        for (int mask = 1; mask < total; mask++) {
            int bit = mask & -mask;
            int v = Integer.numberOfTrailingZeros(bit);
            int prev = mask ^ bit;
            if (!valid[prev]) continue;
            if ((prev & badMaskInside[v]) != 0) continue;
            valid[mask] = true;
            size[mask] = size[prev] + 1;
            forbidOther[mask] = forbidOther[prev] | badMaskOther[v];

            long add = 0;
            int t = prev;
            while (t != 0) {
                int b = t & -t;
                int u = Integer.numberOfTrailingZeros(b);
                add += insideW[v][u];
                t ^= b;
            }
            weight[mask] = weight[prev] + add;
            res.add(new SubsetInfo(mask, size[mask], weight[mask], forbidOther[mask]));
        }
        return res;
    }
}

import sys
from itertools import combinations

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    it = iter(input_data)
    N = int(next(it))
    M = int(next(it))
    K = int(next(it))

    # Friendship matrix, 0 if no edge or c=0
    friend = [[0]*N for _ in range(N)]
    # Conflict matrix for c=0
    conflict = [[False]*N for _ in range(N)]

    for _ in range(M):
        a = int(next(it))
        b = int(next(it))
        c = int(next(it))
        if c == 0:
            conflict[a][b] = True
            conflict[b][a] = True
        else:
            friend[a][b] = c
            friend[b][a] = c

    # Split into two halves
    left_size = N // 2
    right_size = N - left_size
    left_indices = list(range(left_size))
    right_indices = list(range(left_size, N))

    # Precompute conflict masks from left to right
    left_to_right_conflict = [0]*left_size
    for i in range(left_size):
        mask = 0
        for j_idx, j in enumerate(right_indices):
            if conflict[left_indices[i]][j]:
                mask |= (1 << j_idx)
        left_to_right_conflict[i] = mask

    # Precompute internal conflict masks for each half
    left_conflict_mask = [0]*left_size
    for i in range(left_size):
        mask = 0
        for j in range(left_size):
            if conflict[left_indices[i]][left_indices[j]]:
                mask |= (1 << j)
        left_conflict_mask[i] = mask

    right_conflict_mask = [0]*right_size
    for i in range(right_size):
        mask = 0
        for j in range(right_size):
            if conflict[right_indices[i]][right_indices[j]]:
                mask |= (1 << j)
        right_conflict_mask[i] = mask

    # Enumerate all valid subsets of left half
    left_subsets = [[] for _ in range(left_size+1)]  # by size
    for mask in range(1 << left_size):
        # check internal conflicts
        ok = True
        for i in range(left_size):
            if mask & (1 << i):
                if mask & left_conflict_mask[i]:
                    ok = False
                    break
        if not ok:
            continue
        # compute sum and size
        total_sum = 0
        size = 0
        for i in range(left_size):
            if mask & (1 << i):
                size += 1
                for j in range(i+1, left_size):
                    if mask & (1 << j):
                        total_sum += friend[left_indices[i]][left_indices[j]]
        left_subsets[size].append((mask, total_sum))

    # Enumerate all valid subsets of right half
    right_subsets = [[] for _ in range(right_size+1)]
    for mask in range(1 << right_size):
        ok = True
        for i in range(right_size):
            if mask & (1 << i):
                if mask & right_conflict_mask[i]:
                    ok = False
                    break
        if not ok:
            continue
        total_sum = 0
        size = 0
        for i in range(right_size):
            if mask & (1 << i):
                size += 1
                for j in range(i+1, right_size):
                    if mask & (1 << j):
                        total_sum += friend[right_indices[i]][right_indices[j]]
        right_subsets[size].append((mask, total_sum))

    # For each size in right, precompute best sum given a conflict mask
    # We'll store for each size a dict: conflict_mask -> max sum
    best_right = [{} for _ in range(right_size+1)]
    for sz in range(right_size+1):
        for mask, s in right_subsets[sz]:
            # conflict mask from right to left is not needed directly,
            # but we need to check cross conflicts later.
            # For now store by mask to later combine.
            # Actually we need to query by allowed left mask.
            # We'll just store all and iterate over left subsets.
            best_right[sz][mask] = max(best_right[sz].get(mask, -10**18), s)

    ans = -10**18
    for left_sz in range(left_size+1):
        need = K - left_sz
        if need < 0 or need > right_size:
            continue
        for left_mask, left_sum in left_subsets[left_sz]:
            # compute conflict mask from this left subset to right
            cross_conflict_mask = 0
            for i in range(left_size):
                if left_mask & (1 << i):
                    cross_conflict_mask |= left_to_right_conflict[i]
            # For each right subset of size need that doesn't intersect cross_conflict_mask
            for right_mask, right_sum in best_right[need].items():
                if right_mask & cross_conflict_mask:
                    continue
                total = left_sum + right_sum
                # Add cross friendship values
                for i in range(left_size):
                    if left_mask & (1 << i):
                        for j_idx, j in enumerate(right_indices):
                            if right_mask & (1 << j_idx):
                                total += friend[left_indices[i]][j]
                ans = max(ans, total)

    if ans == -10**18:
        print("Impossible")
    else:
        print(ans)

