def solve():
    import sys
    from functools import lru_cache

    data = sys.stdin.read().split()
    idx = 0
    N, M, K = int(data[idx]), int(data[idx+1]), int(data[idx+2])
    idx += 3

    forbidden = [[False]*N for _ in range(N)]
    friendship = [[0]*N for _ in range(N)]

    for _ in range(M):
        a, b, c = int(data[idx]), int(data[idx+1]), int(data[idx+2])
        idx += 3
        a -= 1; b -= 1  # 0-indexed? Let's check - problem says a_i-th monster
        if c == 0:
            forbidden[a][b] = True
            forbidden[b][a] = True
        else:
            friendship[a][b] = c
            friendship[b][a] = c

    # For each monster i, precompute forbidden_mask[i] and friendship contribution when adding i to a set
    # dp[mask] = max sum for subset mask, None if impossible

    INF = float('-inf')
    dp = [INF] * (1 << N)
    dp[0] = 0

    # For each monster i, precompute: forbidden_set as bitmask
    forb_mask = [0] * N
    for i in range(N):
        for j in range(N):
            if forbidden[i][j]:
                forb_mask[i] |= (1 << j)

    for mask in range(1 << N):
        if dp[mask] == INF:
            continue
        # Find lowest unset bit >= highest set bit to avoid recomputation (iterate in order)
        # Actually let's just try adding any monster not in mask
        bits = bin(mask).count('1')
        if bits == K:
            continue
        # Find next monster to add (to avoid duplicates, only add monsters > last in mask)
        last = -1
        for i in range(N-1, -1, -1):
            if mask & (1 << i):
                last = i
                break
        for j in range(last+1, N):
            if mask & (1 << j):
                continue
            # Check if j is forbidden with any monster in mask
            if forb_mask[j] & mask:
                continue
            # Compute friendship gain
            gain = 0
            for i in range(N):
                if mask & (1 << i):
                    gain += friendship[i][j]
            new_mask = mask | (1 << j)
            if dp[new_mask] < dp[mask] + gain:
                dp[new_mask] = dp[mask] + gain

    ans = INF
    for mask in range(1 << N):
        if bin(mask).count('1') == K and dp[mask] != INF:
            ans = max(ans, dp[mask])

    if ans == INF:
        print("Impossible")
    else:
        print(ans)

